def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Find pairs aligned diagonally; extend the matching-color diagonal through
    # background cells, stopping at other colored cells and grid edges.
    pts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                pts.setdefault(grid[r][c], []).append((r,c))
    for color, cells in pts.items():
        for i, (r1,c1) in enumerate(cells):
            for r2,c2 in cells[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == abs(dc) and dr != 0:
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    # Extend from both ends of the observed same-color segment.
                    for rr,cc,step in ((r1-sr,c1-sc,-1),(r2+sr,c2+sc,1)):
                        while 0 <= rr < h and 0 <= cc < w:
                            if out[rr][cc] != bg:
                                break
                            out[rr][cc] = color
                            rr += sr*step
                            cc += sc*step
    return out
